css:
/* The sandbox supplies the height chain; this only lays out the app itself. */
html:has(#webflow-app),body:has(#webflow-app){margin:0}
#webflow-app{height:100%;min-height:0;overflow:hidden}
#webflow-app>.wf-app{display:flex;flex-direction:column;height:100%;min-height:0;overflow:hidden}
.wf-app{--bg:#fff;--paper:#fff;--ink:#1b2c49;--sub:#5b6e86;--line:#dfe6ef;--tint:#f5f7fb;--brand:#365eda;--on-brand:#fff;--warn:#8a5817;--good:#187f62;--focus:#365eda;background:var(--bg);color:var(--ink);font:13px/1.5 -apple-system,BlinkMacSystemFont,"SF Pro Text","PingFang SC",system-ui,sans-serif;min-height:0;color-scheme:light;overflow-wrap:anywhere}
.wf-app[data-theme="dark"]{--bg:#121c2c;--paper:#1b2b40;--ink:#f0f5fe;--sub:#b1c1d8;--line:#35485e;--tint:#273950;--brand:#9db8ff;--on-brand:#121c2c;--warn:#ffce91;--good:#7ed4ad;--focus:#b1c4ff;color-scheme:dark}
@media(prefers-color-scheme:dark){.wf-app[data-theme="system"]{--bg:#121c2c;--paper:#1b2b40;--ink:#f0f5fe;--sub:#b1c1d8;--line:#35485e;--tint:#273950;--brand:#9db8ff;--on-brand:#121c2c;--warn:#ffce91;--good:#7ed4ad;--focus:#b1c4ff;color-scheme:dark}}
.wf-app *,.wf-app *::before,.wf-app *::after{box-sizing:border-box}
.wf-app h1,.wf-app h2,.wf-app h3,.wf-app p{margin:0}
.wf-app h1{font-size:17px;letter-spacing:-.025em}.wf-app h2{font-size:15px;letter-spacing:-.02em}.wf-app h3{font-size:13px}
.wf-app button,.wf-app input,.wf-app select{font:inherit}
.wf-app button{cursor:pointer}.wf-app button:disabled{cursor:not-allowed;opacity:.45}
.wf-app :focus-visible{outline:2px solid var(--focus);outline-offset:2px}
.wf-head{display:flex;flex:none;align-items:center;justify-content:space-between;gap:8px;padding:12px;background:var(--paper);border-bottom:1px solid var(--line)}
.wf-sub,.wf-note,.wf-meta{color:var(--sub)}
.wf-sub,.wf-meta{font-size:11px;line-height:1.5}
.wf-head-actions{display:flex;gap:4px;flex:none}
.wf-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;flex:1;min-width:0}
.wf-tab{border:0;border-radius:7px;background:transparent;color:var(--sub);padding:8px 4px;min-width:44px;min-height:44px;font-weight:640}
.wf-tab[aria-selected=true]{background:var(--tint);color:var(--ink);font-weight:750}
.wf-body{display:grid;flex:1 1 auto;gap:12px;align-content:start;padding:13px 12px 22px;min-width:0;min-height:0;overflow-y:auto;overscroll-behavior-y:contain}
.wf-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:9px}
.wf-heading p{font-size:12px;color:var(--sub)}
.wf-panel{background:var(--paper);border:1px solid var(--line);border-radius:11px;padding:12px;min-width:0}
.wf-stack{display:grid;gap:9px}
.wf-line{display:flex;gap:8px;align-items:center;min-width:0}
.wf-between{justify-content:space-between}.wf-grow{flex:1;min-width:0}
.wf-btn{display:inline-flex;align-items:center;justify-content:center;gap:5px;min-height:33px;border:1px solid var(--line);padding:6px 10px;border-radius:8px;background:var(--paper);color:var(--ink);font-size:12px;font-weight:650;line-height:1.2;text-align:center}
.wf-btn:hover:not(:disabled){background:var(--tint)}
.wf-primary{background:var(--brand);color:var(--on-brand);border-color:var(--brand)}
.wf-primary:hover:not(:disabled){background:var(--brand);filter:brightness(.94)}
.wf-quiet{border-color:transparent;background:transparent;color:var(--brand)}
.wf-icon{width:32px;min-width:32px;min-height:32px;padding:0;font-size:17px}
.wf-metrics{display:flex;flex-wrap:wrap;gap:8px 16px;color:var(--sub);font-size:12px}
.wf-metrics strong{color:var(--ink);font-variant-numeric:tabular-nums}
.wf-banner{padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--tint);font-size:12px}
.wf-warning{border-color:#d8b482;background:#fff7ea;color:#734510}
.wf-app[data-theme="dark"] .wf-warning{background:#342b20;color:#ffdfa6;border-color:#866743}
.wf-badge{display:inline-flex;align-items:center;gap:5px;color:var(--sub);font-size:11px;white-space:nowrap}
.wf-badge::before{content:"";width:7px;height:7px;display:inline-block;background:#95a4b8;border-radius:50%}
.wf-badge[data-state="available"]::before{background:var(--good)}
.wf-badge[data-state="changed"]::before,.wf-badge[data-state="runtime"]::before,.wf-badge[data-state="unavailable"]::before,.wf-badge[data-state="error"]::before{background:#cf9750}
.wf-badge[data-state="running"]::before{background:#638ce0}
.wf-task{display:grid;gap:8px}
.wf-task-title{display:flex;align-items:center;gap:8px;min-width:0}
.wf-task-icon{display:grid;place-items:center;width:31px;height:31px;flex:none;border-radius:9px;border:1px solid var(--line);background:var(--tint);font-size:15px;font-weight:750}
.wf-task-title strong{font-size:13px;display:block}
.wf-actions{display:flex;flex-wrap:wrap;gap:6px}
.wf-input,.wf-select{background:var(--paper);color:var(--ink);display:block;width:100%;min-width:0;border:1px solid #8698b0;border-radius:8px;padding:8px 10px;min-height:35px;font-size:13px}
.wf-label{display:grid;gap:4px;font-size:12px;font-weight:650}
/* Tool-owned, accessible switch. The trusted Host does not expose its React Switch to sandboxes. */
.wf-switch-row{display:flex;align-items:center;justify-content:space-between;gap:12px;min-width:0}
.wf-switch-description{display:grid;gap:3px;min-width:0;flex:1}
.wf-switch-description strong{font-size:13px;font-weight:650}
.wf-switch-description .wf-sub{font-weight:400;font-size:11px}
.wf-switch-control{display:flex;align-items:center;justify-content:center;width:44px;min-height:26px;flex:none}
.wf-switch-native{position:relative;display:block;width:44px;height:26px;cursor:pointer}
.wf-switch-native input{position:absolute;inset:0;z-index:1;margin:0;width:100%;height:100%;opacity:0;cursor:pointer}
.wf-switch-track{display:block;width:44px;height:26px;border-radius:999px;background:var(--line);border:1px solid var(--sub);transition:background .15s ease}
.wf-switch-track::after{content:"";display:block;width:20px;height:20px;margin:2px;border-radius:50%;background:var(--paper);box-shadow:0 1px 4px #0003;transition:transform .15s ease}
.wf-switch-native input:checked+.wf-switch-track{background:var(--brand);border-color:var(--brand)}
.wf-switch-native input:checked+.wf-switch-track::after{transform:translateX(18px);background:var(--on-brand)}
.wf-switch-native input:focus-visible+.wf-switch-track{outline:2px solid var(--focus);outline-offset:3px}
.wf-switch-native input:disabled+.wf-switch-track{opacity:.55}
.wf-switch-native:has(input:disabled){cursor:default}
@media(prefers-reduced-motion:reduce){.wf-switch-track,.wf-switch-track::after{transition:none}}
.wf-filter{display:flex;gap:5px;overflow:auto;scrollbar-width:thin}
.wf-chip{border:1px solid var(--line);background:var(--paper);border-radius:999px;padding:5px 10px;white-space:nowrap;color:var(--sub);font-size:12px}
.wf-chip[aria-pressed=true]{background:var(--tint);border-color:#90a9d4;color:var(--ink)}
.wf-detail{display:grid;grid-template-columns:minmax(65px,1fr) minmax(0,2fr);gap:6px 9px;font-size:12px}
.wf-detail dt{color:var(--sub)}.wf-detail dd{margin:0;overflow-wrap:anywhere}
.wf-mono{font:11px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}
.wf-result{margin:0;white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace}
.wf-empty{text-align:center;padding:22px 12px;display:grid;gap:6px}
.wf-empty strong{font-size:14px}
.wf-error{color:#b94a56}.wf-ok{color:var(--good)}.wf-warn{color:var(--warn)}
.wf-help{font-size:12px;line-height:1.75;color:var(--sub)}
.wf-help summary{font-weight:700;color:var(--ink);cursor:pointer}
.wf-overview{font-size:14px}
.wf-overview :is(.wf-sub,.wf-metrics,.wf-help){font-size:14px}
.wf-overview .wf-heading{align-items:center}
.wf-overview .wf-metrics>span{white-space:nowrap}
.wf-overview .wf-warning .wf-btn{flex:none}
.wf-overview h3{font-size:14px}
.wf-overview .wf-btn{min-height:44px;font-size:14px}
.wf-onboarding>summary{display:flex;align-items:center;gap:8px;min-height:44px;cursor:pointer;font-weight:700;list-style:none}
.wf-onboarding>summary::-webkit-details-marker{display:none}
.wf-onboarding>summary::before{content:"";flex:none;width:7px;height:7px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:rotate(-45deg)}
.wf-onboarding[open]>summary::before{transform:rotate(45deg)}
.wf-onboarding>div{padding-top:9px}
.wf-onboarding ol{margin:0;padding-inline-start:22px}
.wf-history{list-style:none;margin:0;padding:0;display:grid;gap:8px}
.wf-loading{padding:20px;color:var(--sub)}
@media(min-width:520px){.wf-body{padding:17px 18px 25px}.wf-head{padding:13px 18px}}
@media(max-width:350px){.wf-body{padding:10px 9px 20px}.wf-head{padding:9px}.wf-panel{padding:10px}.wf-btn{padding:5px 8px}}
@media(prefers-reduced-motion:reduce){.wf-app *{animation:none!important;transition:none!important}}

/* V0.3.2: compact sandbox body only. The single Host Header and trusted
   runtime sheet live outside the opaque-origin iframe. */
.wf-head{padding:0 9px;gap:4px;min-width:0}
.wf-tabs{gap:0}
.wf-tab{position:relative;min-height:43px;border-radius:0;padding:7px 4px;font-size:12px}
.wf-tab[aria-selected=true]{background:transparent;color:var(--brand)}
.wf-tab[aria-selected=true]::after{content:"";position:absolute;height:2px;left:21%;right:21%;bottom:0;background:var(--brand)}
.wf-head-actions{gap:2px;padding-left:4px;border-left:1px solid var(--line)}
.wf-head-actions .wf-btn{gap:4px;padding:6px;min-height:40px;white-space:nowrap;color:var(--sub)}
.wf-head-actions .wf-btn[aria-current="page"]{background:var(--tint);color:var(--brand)}
.wf-body{gap:10px;padding:12px;min-width:0}
.wf-overview{font-size:13px}
.wf-overview :is(.wf-sub,.wf-metrics,.wf-help){font-size:11px}
.wf-overview .wf-btn{min-height:34px;font-size:11px}
.wf-overview h3{font-size:12px}
.wf-overview .wf-panel{padding:10px}
.wf-metrics{gap:6px 14px;font-size:11px}
.wf-task-list,.wf-history{border:1px solid var(--line);border-radius:10px;background:var(--paper);min-width:0}
.wf-task-row{position:relative;padding:9px 7px;min-width:0}
.wf-task-row+.wf-task-row,.wf-record-row+.wf-record-row{border-top:1px solid var(--line)}
.wf-task-main{display:grid;grid-template-columns:29px minmax(0,1fr) auto;align-items:center;gap:7px;min-width:0}
.wf-task-icon{width:29px;height:29px;border:0;border-radius:8px;font-size:13px}
.wf-task-info{min-width:0;overflow:hidden}
.wf-app .wf-task-name{display:block;max-width:100%;width:100%;padding:0;border:0;background:none;color:var(--ink);font-size:12px;font-weight:700;line-height:1.5;text-align:left;text-overflow:ellipsis;overflow:hidden;white-space:nowrap}
.wf-task-meta{display:flex;align-items:center;gap:5px;min-width:0;overflow:hidden}
.wf-task-meta .wf-badge{min-width:0;flex:none;font-size:10px}
.wf-task-meta .wf-badge::before{width:6px;height:6px}
.wf-truncate{display:inline-block;max-width:min(43%,125px);min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--sub);font-size:10px}
.wf-item-buttons{display:flex;align-items:center;gap:0;flex:none}
.wf-item-buttons .wf-icon{width:29px;min-width:29px;min-height:31px;padding:0;border-color:transparent}
.wf-item-buttons .wf-icon svg,.wf-head-actions .wf-icon svg{width:17px;height:17px}
.wf-item-buttons .wf-primary{background:var(--tint);color:var(--brand);border-color:transparent}
.wf-item-buttons .wf-primary:hover:not(:disabled){background:var(--tint)}
.wf-menu-anchor{position:relative}
.wf-menu{position:absolute;right:0;top:35px;z-index:20;min-width:154px;display:grid;gap:2px;padding:5px;background:var(--paper);border:1px solid var(--line);border-radius:9px;box-shadow:0 12px 25px #142d4830}
.wf-menu button{background:transparent;color:var(--ink);border:0;border-radius:6px;padding:8px 9px;text-align:left;min-height:34px;font-size:11px}
.wf-menu button:hover:not(:disabled){background:var(--tint)}
.wf-row-error{margin-top:7px}
.wf-task-detail{background:var(--tint);border-radius:8px;margin-top:8px;padding:10px;min-width:0}
.wf-search-row{display:grid;grid-template-columns:minmax(0,1fr) repeat(3,34px);gap:6px;align-items:center;position:relative;min-width:0}
.wf-search-input{min-width:0;min-height:36px}
.wf-search-row>.wf-icon{width:34px;min-width:34px;height:34px;min-height:34px;padding:0}
.wf-filter-popover{display:grid;gap:3px;position:absolute;z-index:19;right:0;top:43px;width:min(230px,100%);padding:10px;border:1px solid var(--line);border-radius:10px;background:var(--paper);box-shadow:0 12px 26px #142d4830}
.wf-filter-popover>strong{font-size:11px}
.wf-filter-option{background:transparent;color:var(--ink);border:0;border-radius:6px;padding:8px;text-align:left;min-height:32px;font-size:11px}
.wf-filter-option:hover,.wf-filter-option[aria-pressed=true]{background:var(--tint);color:var(--brand)}
.wf-filter-popover .wf-label{margin-top:4px}
.wf-filter-popover .wf-select{min-height:34px;font-size:11px}
.wf-history{padding:0;gap:0;overflow:visible}
.wf-record-row{list-style:none;min-width:0}
.wf-record-details summary{cursor:pointer;list-style:none}
.wf-record-details summary::-webkit-details-marker{display:none}
.wf-record-summary{display:flex;align-items:center;gap:8px;padding:8px 9px;min-width:0}
.wf-record-info{flex:1;min-width:0;overflow:hidden}
.wf-record-info strong{display:block;font-size:12px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wf-record-info .wf-sub{display:block;font-size:10px}
.wf-record-summary .wf-badge{max-width:90px;min-width:0;overflow:hidden;text-overflow:ellipsis;font-size:10px}
.wf-chevron{flex:none;display:flex;color:var(--sub)}
.wf-chevron svg{width:15px;height:15px}
.wf-record-details[open] .wf-chevron{transform:rotate(90deg)}
.wf-record-expanded{background:var(--tint);padding:10px;border-radius:8px;margin:0 8px 8px;min-width:0}
.wf-record-expanded .wf-detail{grid-template-columns:minmax(70px,1fr) minmax(0,2fr)}
@media(min-width:520px){.wf-head{padding:0 12px}.wf-body{padding:14px 15px}}
@media(max-width:350px){.wf-head{padding:0 5px}.wf-body{padding:9px}.wf-task-main{gap:4px}.wf-task-row{padding:8px 5px}.wf-item-buttons .wf-icon{width:27px;min-width:27px}.wf-record-summary{padding:7px}}


/* Script rows reuse the host's information hierarchy without crossing the iframe authority boundary. */
.wf-task-row[data-menu-open="true"]{z-index:4}
.wf-task-icon{background:#eaf0ff;color:var(--brand)}
.wf-app[data-theme="dark"] .wf-task-icon{background:var(--tint)}
@media(prefers-color-scheme:dark){.wf-app[data-theme="system"] .wf-task-icon{background:var(--tint)}}
.wf-item-buttons .wf-icon:not(.wf-primary){opacity:.55}
.wf-task-row:is(:hover,:focus-within) .wf-icon:not(.wf-primary),.wf-task-row[data-menu-open="true"] .wf-icon{opacity:1}
@media(hover:none){.wf-item-buttons .wf-icon:not(.wf-primary){opacity:1}}
.wf-task-detail-heading{display:flex;align-items:center;justify-content:space-between;gap:8px}
.wf-task-detail-heading .wf-icon{width:26px;min-width:26px;min-height:26px}
.wf-task-technical{border-top:1px solid var(--line);padding-top:6px}
.wf-task-technical>summary{cursor:pointer;color:var(--sub)}
.wf-task-technical .wf-detail{margin:8px 0 0}
.wf-task-detail .wf-sub{white-space:normal;overflow-wrap:anywhere}
.wf-tab-dot{display:inline-block;width:5px;height:5px;margin-left:5px;border-radius:50%;background:var(--warn);vertical-align:middle}
.wf-configure-feedback{color:var(--warn);font-size:11px;min-width:0}
.wf-configure-feedback>summary{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:28px;cursor:pointer;list-style:none}
.wf-configure-feedback>summary::-webkit-details-marker{display:none}
.wf-configure-feedback>summary::after{content:"›";font-size:16px}
.wf-configure-feedback>summary>.wf-sub{margin-left:auto}
.wf-configure-feedback[open]>summary::after{transform:rotate(90deg)}
.wf-configure-feedback>div{padding:8px 0;border-top:1px solid var(--line)}
.wf-configure-feedback .wf-btn{min-height:28px;font-size:11px;padding:4px 6px}

/* R1 script onboarding lives inside the sandbox, never in the trusted TaskRunSheet. */
.wf-add-sheet{background:var(--paper);border:1px solid var(--line);border-radius:10px;padding:12px;min-width:0}
.wf-add-sheet .wf-line{flex-wrap:wrap}
.wf-add-way{width:100%;min-height:54px;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:2px 8px;align-items:center;text-align:left;border:1px solid var(--line);border-radius:9px;background:var(--paper);color:var(--ink);padding:9px 11px}
.wf-add-way:hover{background:var(--tint);border-color:var(--brand)}
.wf-add-way strong{grid-column:1;font-size:12px}
.wf-add-way small{grid-column:1;color:var(--sub);font-size:11px}
.wf-add-way>span{grid-column:2;grid-row:1/span 2;color:var(--sub)}
.wf-add-installed{display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:9px;border:1px solid var(--line);border-radius:8px}
.wf-add-installed .wf-grow strong,.wf-add-installed .wf-grow small{display:block;overflow-wrap:anywhere}
.wf-add-installed .wf-grow small{font-size:10px;color:var(--sub)}
.wf-add-input{resize:vertical;min-height:66px}
.wf-add-prompt{font:11px/1.55 ui-monospace,Consolas,monospace;min-height:150px;max-height:310px}
.wf-add-sheet .wf-label{font-size:11px}
@media(max-width:350px){.wf-search-row{gap:4px;grid-template-columns:minmax(0,1fr) repeat(3,32px)}.wf-search-row>.wf-icon{width:32px;min-width:32px;height:32px;min-height:32px}}

